# ---------------------------------------------------------------------------
# 【本仓库改动】公式区域支持
#
# pdf2docx **没有任何公式概念**:它只按几何猜布局(一行里元素间距 ≥ 5pt 就算非流式,
# 判成 stream table),而公式碎片之间的空档正好是 15~20pt —— 于是整块公式连同周围
# 正文被攒进同一张表;上下标只表现为字号差,分式、根号的结构全部丢失。
#
# 所以让调用方先在 PDF 上把公式区域定位出来(见 src/import/scripts/formula_extract.py),
# 通过 ``formula_regions`` 参数传进来。这里做两件事:
#   1. 把这些区域里的**行**从文本块中剔掉(按行剔,公式和正文可能同处一块);
#   2. 把区域渲染成图片,当作 image block 注入 —— IMAGE 是 pdf2docx 已有的类型,
#      ImageBlock → ImageSpan → run 这条链路是通的,位置尺寸按 bbox 精确还原。
#
# 之后由 formula_ocr.py 把这些图片按 1:1 换成 OMML。docx 里那处就是一张图,
# 不再需要"编号是否落在段尾""是不是单行表格"这类形态判据 ——
# 那些判据正是原位替换数量在 6~9 之间抖动的原因。
# ---------------------------------------------------------------------------

def _inside_formula(bbox, 公式区, 阈值=0.5):
    '''这个 bbox 是否**主要**落在某个公式区域里(交叠面积占比 ≥ 阈值)。'''
    bb = fitz.Rect(bbox)
    面积 = bb.get_area()
    if 面积 <= 0:
        return False
    for f in 公式区:
        fr = fitz.Rect(f['bbox'])
        if not bb.intersects(fr):
            continue
        if (bb & fr).get_area() / 面积 >= 阈值:
            return True
    return False


def _strip_formula_lines(block, 公式区):
    '''剔掉落在公式区域里的内容;整块都被剔掉时返回 None。

    分两级(都是实测逼出来的):
    * 整行的 bbox 都在公式区里 → 整行删;
    * 只有**部分 span** 在公式区里 → 只删那些 span。因为 PyMuPDF 会把
      "正文 + 公式编号"切在同一行里(同一基线),实测第 5 页就是
      ``are computed as:`` 和 ``(2)`` 同处一行、相隔 300pt —— 整行判不透,
      而 pdf2docx 又会按这个间距把它排成两列表格。
    按 span 剔之后,这一行只剩正文,不再被判成表格。
    '''
    lines = block.get('lines', [])
    if not lines:
        return block

    新行们 = []
    for ln in lines:
        if _inside_formula(ln['bbox'], 公式区):
            continue                          # 整行落在公式区
        spans = ln.get('spans', [])
        留着 = [s for s in spans if not _inside_formula(s['bbox'], 公式区)]
        if len(留着) == len(spans):
            新行们.append(ln)                  # 这一行没碰到公式
            continue
        if not 留着:
            continue
        new_line = dict(ln)
        new_line['spans'] = 留着
        bb = fitz.Rect(留着[0]['bbox'])
        for s in 留着[1:]:
            bb |= fitz.Rect(s['bbox'])
        new_line['bbox'] = tuple(bb)
        新行们.append(new_line)

    if len(新行们) == len(lines):
        return block
    if not 新行们:
        return None
    new = dict(block)
    new['lines'] = 新行们
    bb = fitz.Rect(新行们[0]['bbox'])
    for ln in 新行们[1:]:
        bb |= fitz.Rect(ln['bbox'])
    new['bbox'] = tuple(bb)
    return new


def _行文本(ln):
    '''取一行的文本。rawdict 的字符在 ``chars`` 里,``text`` 往往是空的。'''
    片 = []
    for sp in ln.get('spans', []):
        chars = sp.get('chars')
        if chars:
            片.append(''.join(c.get('c') or '' for c in chars))
        else:
            片.append(sp.get('text') or '')
    return ''.join(片)


def _是边缘竖排(block, 页宽, 页高):
    '''是不是"贴着页面边缘的竖排短文"(arXiv 首页左侧那种侧栏标记)。

    为什么必须摘掉它:``Collection.is_flow_layout()`` 里有一句
    "竖排文本按 stream table 模拟",只要这一行在,它所在的那一片就被判成
    非流式布局 → 整块当表格。而为了把这行竖排字框进去,表格会横向一路扩到
    正文里 —— 实测第 1 页 `arXiv:2610.28171v1 [cs.CV] 20 Oct 2026` 就是这样
    把正文卷进表格的。

    判据三条一起:竖排、贴近左右边缘、字数很少。
    '''
    行们 = block.get('lines', [])
    if not 行们:
        return False

    # 竖排:wmode 非 0,或书写方向不是水平的
    竖 = False
    for ln in 行们:
        if ln.get('wmode'):
            竖 = True
            break
        d = ln.get('dir') or [1.0, 0.0]
        if abs(d[0]) < 0.5:
            竖 = True
            break
    if not 竖:
        return False

    # 字数很少(侧栏标记是短句,不是正文)。
    # 注意:rawdict 里字符在 chars,text 是空的 —— 用 text 统计会永远是 0。
    字数 = sum(len(_行文本(ln)) for ln in 行们)
    if 字数 == 0 or 字数 > 80:
        return False

    # 贴着左右边缘
    bb = fitz.Rect(block['bbox'])
    return bb.x1 < 页宽 * 0.12 or bb.x0 > 页宽 * 0.88


def _摘掉边缘竖排(块们, 页宽, 页高):
    '''把边缘竖排短文摘出来,返回 (留下的块, [(bbox, 文本)])。

    摘下来的文字不丢,由调用方挂到别的块末尾;但**必须先从块里摘走** ——
    它留在原位会把整片版面拖成表格。
    '''
    留 = []
    摘 = []
    for b in 块们:
        if b.get('type') != 0:
            留.append(b)
            continue
        if not _是边缘竖排(b, 页宽, 页高):
            留.append(b)
            continue
        片 = [t for t in (_行文本(ln).strip() for ln in b.get('lines', [])) if t]
        if 片:
            摘.append((fitz.Rect(b['bbox']), ' '.join(片)))
    return 留, 摘


def _追加文字到块(block, 文本, 字高=9.0):
    '''把一段文字作为新的一行,追加到已有文本块的末尾。

    为什么不用"新建一个块":新建的块容易被 pdf2docx 的清��/页脚识别环节丢掉
    (实测放在页面底部 y=页高-100 仍然不见了)。挂在已有块上则一定会输出。

    文字会显示在那一块的最后一行下面,字号小一号 —— 对 arXiv 侧栏那种
    "卷期编号"元信息来说,这样处理足够了。
    '''
    行们 = block.get('lines', [])
    if not 行们:
        return False

    末 = 行们[-1]
    末bb = fitz.Rect(末['bbox'])
    y0 = 末bb.y1 + 2.0
    宽 = max(60.0, len(文本) * 字高 * 0.62)

    chars = []
    x = 末bb.x0
    for ch in 文本:
        chars.append({
            'c': ch,
            'origin': (x, y0 + 字高),
            'bbox': (x, y0, x + 字高 * 0.62, y0 + 字高),
        })
        x += 字高 * 0.62

    新行 = {
        'bbox': (末bb.x0, y0, 末bb.x0 + 宽, y0 + 字高),
        'wmode': 0,
        'dir': [1.0, 0.0],
        'spans': [{
            'size': 字高, 'flags': 0, 'font': 'helv', 'color': 0,
            'ascender': 1.0, 'descender': -0.2,
            'origin': (末bb.x0, y0 + 字高),
            'bbox': (末bb.x0, y0, 末bb.x0 + 宽, y0 + 字高),
            'text': 文本,
            'chars': chars,
        }],
    }
    行们.append(新行)

    bb = fitz.Rect(block['bbox'])
    新bb = bb | fitz.Rect(新行['bbox'])
    block['bbox'] = tuple(新bb)
    return True


class RawPageFitz(RawPage):
    '''A wrapper of ``fitz.Page`` to extract source contents.'''

    def extract_raw_dict(self, **settings):
        raw_dict = {}
        if not self.page_engine: return raw_dict

        # actual page size
        # `self.page_engine` is the `fitz.Page`.
        *_, w, h = self.page_engine.rect # always reflecting page rotation
        raw_dict.update({ 'width' : w, 'height': h })
        self.width, self.height = w, h

        # 本页的公式区域(坐标是 PDF 坐标系;``page`` 是 0 起的页索引)
        # 剔文字用「区域」(含编号,否则 docx 里会剩个孤立的 "(2)" 和图片挤在一段);
        # 注入图片用 bbox(裁图不该带编号,编号由 OMML 那边补)。
        公式区 = [f for f in (settings.get('formula_regions') or [])
                  if f.get('page') == self.page_engine.number]
        剔区 = [{'bbox': f.get('区域') or f['bbox']} for f in 公式区]

        # 矢量图必须先处理:它决定了"哪些文字已经被画进图里"。
        shapes, images =  self._preprocess_shapes(**settings)

        # pre-processing layout elements. e.g. text, images and shapes
        text_blocks = self._preprocess_text(**settings)

        # 【本仓库改动】先把"贴着页面边缘的竖排短文"摘出来。
        # pdf2docx 的 is_flow_layout() 里有一句"竖排文本按 stream table 模拟",
        # 只要这行字还在,它所在的那一片就被判成表格,而且为了把它框进去,
        # 表格会横向一路扩到正文里 —— 实测第 1 页左侧的
        # `arXiv:2610.28171v1 [cs.CV] 20 Oct 2026` 就是这样把正文卷进表格的。
        # 摘出来之后它不参与任何版面判断(也不会被并进矢量图),内容另行挂到块尾。
        页宽 = self.page_engine.rect.width
        页高 = self.page_engine.rect.height
        text_blocks, 边缘竖排 = _摘掉边缘竖排(text_blocks, 页宽, 页高)
        竖排bb = [bb for bb, _ in 边缘竖排]

        # 图区扩到"图里的刻度/图例"(排除已摘走的边缘竖排),再按新范围重裁
        if images:
            images = self._expand_svg_to_include_labels(images, settings, 跳过bb=竖排bb)

        if 剔区:
            text_blocks = [b for b in (_strip_formula_lines(b, 剔区) for b in text_blocks) if b]

        # ------------------------------------------------------------------
        # 【本仓库改动】落进矢量图里的文字要剔掉 —— 否则同一份内容会输出两次。
        #
        # pdf2docx 会把"一堆矢量绘图"合并渲染成一张位图(如第 5 页的 Figure 4),
        # 但那些图里的**文字仍然是文本层的字符**,于是又单独提取了一份出来。
        # 实测第 5 页这张图里有 7 个文字块被完整覆盖在里面('Affinity'、'1x1 Conv'、
        # 'Aggregation'、'Split'、'Q' …),在 docx 里各摆各的位置 —— 这就是
        # "图片和文字对不上"的来源:不是位置算错,是同一份内容被输出了两次。
        #
        # 只处理矢量图渲染出的位图(真正的位图本来就没有文字层),表格完全不动;
        # 图注在图外,不受影响。再加一道保险:整页级别的图区不动手,免得把整页文字剔光。
        # ------------------------------------------------------------------
        图区 = []
        if images:
            页面积 = max(self.page_engine.rect.get_area(), 1.0)
            图区 = [{'bbox': b['bbox']} for b in images
                    if fitz.Rect(b['bbox']).get_area() < 页面积 * 0.6]
        if 图区:
            text_blocks = [b for b in (_strip_formula_lines(b, 图区) for b in text_blocks) if b]

        # 摘下来的边缘竖排文字**不在这里输出** —— 由我们侧(插入竖排文本框)按 PDF
        # 原始坐标重建一个绝对定位的竖排文本框。这里再塞一份就是重复内容了。
        # 但要留个记录,免得"摘了却没人接";见 formula_ocr.py 的 插入竖排文本框()。

        raw_dict['blocks'] = text_blocks

        image_blocks = self._preprocess_images(**settings)
        # 成组的小图(网格 + 其中的标签)整片截成一张图 —— 见 _snapshot_grids
        image_blocks, text_blocks, 网格数 = self._snapshot_grids(
            image_blocks, text_blocks, settings)
        if 网格数:
            raw_dict['blocks'] = text_blocks
        raw_dict['blocks'].extend(image_blocks)

        raw_dict['shapes'] = shapes
        raw_dict['blocks'].extend(images)

        hyperlinks = self._preprocess_hyperlinks()
        raw_dict['shapes'].extend(hyperlinks)        
       
        # 公式图片块:最后追加,位置由 bbox 决定
        if 公式区:
            raw_dict['blocks'].extend(self._formula_image_blocks(公式区, settings))

        # Element is a base class processing coordinates, so set rotation matrix globally
        Element.set_rotation_matrix(self.page_engine.rotation_matrix)

        return raw_dict
    

    def _snapshot_grids(self, image_blocks, text_blocks, settings):
        '''把"成组的小图 + 其中的标签文字"整片截成一张图。

        为什么不在 docx 层拼:pdf2docx 输出时每个 image block 一个段落,Figure 3
        那种 2x6 缩略图会散成 12 段;而标签(Newspaper/Paper/Magazine)是独立文字块,
        两者在 Layout 里被分到不同的 group,顺序怎么调都对不上(实测把 raw blocks
        排序、把 Blocks.make_docx 排序都被上层分组覆盖)。

        用户建议改成整片截图 —— 对外观而言这就是 1:1:裁的是 PDF 渲染结果,
        网格、标签、相对位置全都原样保留,而且只产生**一张图**,
        不会再出现"图一段、标签一段"的错位。

        只处理"成组的小图":>=3 张、彼此间隙 <= 20pt(网格特征)。
        这个 20 是量出来的:实测第 4 页 Figure 3 两行缩略图之间的垂直间隙是
        14pt,阈值取 12 会把一个网格拆成两张图(各 216x46,标签也没被吞进来)。
        '''
        if not image_blocks or len(image_blocks) < 3:
            return image_blocks, text_blocks, 0

        矩形们 = [fitz.Rect(b['bbox']) for b in image_blocks]

        # 并查集:间隙 <= 20pt 的图归为一组
        组号 = list(range(len(image_blocks)))

        def 根(i):
            while 组号[i] != i:
                组号[i] = 组号[组号[i]]
                i = 组号[i]
            return i

        for i in range(len(矩形们)):
            for j in range(i + 1, len(矩形们)):
                a, b = 矩形们[i], 矩形们[j]
                dx = max(a.x0 - b.x1, b.x0 - a.x1, 0)
                dy = max(a.y0 - b.y1, b.y0 - a.y1, 0)
                if max(dx, dy) <= 20:
                    组号[根(i)] = 根(j)

        组们 = {}
        for i in range(len(image_blocks)):
            组们.setdefault(根(i), []).append(i)

        ie = ImagesExtractor(self.page_engine)
        ratio = settings.get('clip_image_res_ratio', 4.0)
        剩余图 = []
        已并 = set()
        新图 = []
        吞框们 = []

        for 成员 in 组们.values():
            if len(成员) < 3:
                continue                       # 不是网格,保持原样
            并 = fitz.Rect(矩形们[成员[0]])
            for k in 成员[1:]:
                并 |= 矩形们[k]

            # 把落在网格范围内的标签文字也框进来(它们才是"图注")
            文字bb们 = []
            for b in text_blocks:
                if b.get('type') != 0:
                    continue
                bb = fitz.Rect(b['bbox'])
                if bb.is_empty:
                    continue
                交 = bb & 并
                if not 交.is_empty and 交.get_area() >= bb.get_area() * 0.6:
                    文字bb们.append(bb)

            # 向上/向下各留一点余量,别把贴边的标签切掉
            框 = fitz.Rect(并)
            for bb in 文字bb们:
                框 |= bb

            # 紧跟其下的**题注**(Figure/Table N: …)也一起截进来。
            # 不截的话它在 docx 里是独立段落,和图的先后关系靠排版顺序保证,
            # 一旦顺序错位就又变成"图注对不上";截进图里则外观 100% 等于原文。
            for b in text_blocks:
                if b.get('type') != 0:
                    continue
                bb = fitz.Rect(b['bbox'])
                if bb.is_empty:
                    continue
                文本 = ''.join(_行文本(ln) for ln in b.get('lines', [])).strip()
                if not re.match(r'(Figure|Table|Algorithm)\s*S?\d', 文本, re.I):
                    continue
                # 必须在框的下方、且水平方向有交叠(同一张图的注)
                if bb.y0 < 框.y1 - 6 or bb.y0 > 框.y1 + 60:
                    continue
                if bb.x0 > 框.x1 or bb.x1 < 框.x0:
                    continue
                框 |= bb

            框 = fitz.Rect(框.x0 - 2, 框.y0 - 2, 框.x1 + 2, 框.y1 + 2)
            框 = 框 & self.page_engine.rect

            try:
                新图.append(ie.clip_page_to_dict(bbox=框, rm_image=False,
                                                 clip_image_res_ratio=ratio,
                                                 rm_text=True))
                已并.update(成员)
                吞框们.append(框)          # 记下框,稍后把框里的文字一并剔除
            except Exception:
                logging.warning('snapshot grid failed: %s', 框)

        # 被截进图里的文字要从 blocks 剔除,否则同一份内容会输出两次:
        # 既在截图里、又是独立段落(标签和题注都会这样重复)。
        被吞文字 = set()
        for b in text_blocks:
            if b.get('type') != 0:
                continue
            bb = fitz.Rect(b['bbox'])
            if bb.is_empty:
                continue
            for 框 in 吞框们:
                交 = bb & 框
                if not 交.is_empty and 交.get_area() >= bb.get_area() * 0.6:
                    被吞文字.add(id(b))
                    break

        剩余图 = [b for i, b in enumerate(image_blocks) if i not in 已并]
        剩余字 = [b for b in text_blocks if id(b) not in 被吞文字]
        return 剩余图 + 新图, 剩余字, len(新图)

    def _merge_adjacent_images(self, blocks, settings, 间隙=10.0, 最少个数=3):
        '''把排成网格的小图合并成一张图。

        pdf2docx 输出时**每个 image block 一个段落**,所以 Figure 3 那种
        "6 列 x 2 行共 12 张文档页缩略图"的网格,会变成 12 个段落从上到下排 ——
        完全不是原来的网格(用户实测反馈)。

        不恢复浮动(浮动会压在图注上、还会把正文拱进表格),而是**合并**:
        把间隙很小的一组小图并成一个 bbox,按这个范围重新裁页面(保留页面上的位图)。
        合并后仍是一张**行内图** —— 不重叠、不出表格、体积正确,视觉上还是网格。

        只并"个数够多"的组:两张图挨着可能本来就该分开,3 张以上几乎都是网格。
        '''
        if not blocks or len(blocks) < 最少个数:
            return blocks

        矩形们 = [fitz.Rect(b['bbox']) for b in blocks]

        # 贪心分组:两两间隙 <= 间隙 就并到一组(并查集)
        组号 = list(range(len(blocks)))

        def 根(i):
            while 组号[i] != i:
                组号[i] = 组号[组号[i]]
                i = 组号[i]
            return i

        for i in range(len(矩形们)):
            for j in range(i + 1, len(矩形们)):
                a, b = 矩形们[i], 矩形们[j]
                dx = max(a.x0 - b.x1, b.x0 - a.x1, 0)
                dy = max(a.y0 - b.y1, b.y0 - a.y1, 0)
                if max(dx, dy) <= 间隙:
                    组号[根(i)] = 根(j)

        组们 = {}
        for i in range(len(blocks)):
            组们.setdefault(根(i), []).append(i)

        ie = ImagesExtractor(self.page_engine)
        ratio = settings.get('clip_image_res_ratio', 4.0)
        结果 = []
        已并 = set()
        for 成员 in 组们.values():
            if len(成员) < 最少个数:
                continue                      # 张数不够,可能有别的含义,不并
            并 = fitz.Rect(矩形们[成员[0]])
            for k in 成员[1:]:
                并 |= 矩形们[k]
            try:
                # rm_image=False:保留页面上的原始位图,否则裁出来是空的;
                # rm_text=True:网格图里不该夹着正文
                结果.append(ie.clip_page_to_dict(bbox=并, rm_image=False,
                                                 clip_image_res_ratio=ratio,
                                                 rm_text=True))
                已并.update(成员)
            except Exception:
                logging.warning('merge adjacent images failed: %s', 并)

        # 没被合并的原样保留
        for i, b in enumerate(blocks):
            if i not in 已并:
                结果.append(b)
        return 结果

    def _expand_svg_to_include_labels(self, images, settings, 跳过bb=None):
        '''把图区扩到"图里的文字",再按新范围重裁(裁图保留文字)。

        图区的 bbox 只圈住**绘图区**,而图例、坐标轴刻度、轴标题常常在外面:
        实测第 1 页 `YOLOv8` 在图区内、刻度 `1.5` 只跟底边重叠 1.5pt、
        轴标题 `M6Doc mAP50:95 (%)` 干脆在图左外侧。裁图从边上一刀切,这些字
        就没进图;而文本层里它们还在,又被单独提取、排成表格 —— 图和文字分家。

        并入的判据(两个都要满足),实测这两条能把图内文字和正文干净分开:
        * **靠近**:与图区交叠,或距离 ≤ 15pt;
        * **字号明显更小**:小于本页正文常见字号的 0.8 倍。
          第 1 页实测:正文/作者单位是 10pt、图内文字是 5.3~6.9pt。
        只靠"靠近"会把图的作者单位 `Shanghai AI Laboratory` 也吞进来(它离图 9pt)。
        '''
        文字们 = []          # [(Rect, size)]
        字号们 = []
        for b in self.page_engine.get_text('dict')['blocks']:
            if b.get('type') != 0:
                continue
            for ln in b.get('lines', []):
                for s in ln.get('spans', []):
                    if not (s.get('text') or '').strip():
                        continue
                    文字们.append((fitz.Rect(s['bbox']), float(s.get('size') or 0)))
                    字号们.append(float(s.get('size') or 0))
        if not 文字们:
            return images

        # 本页正文的常见字号(用中位数,避开标题的超大字号)
        字号们.sort()
        正文号 = 字号们[len(字号们) // 2] or 10.0
        阈值 = 正文号 * 0.8

        ie = ImagesExtractor(self.page_engine)
        ratio = settings.get('clip_image_res_ratio', 4.0)
        结果 = []
        for img in images:
            原 = fitz.Rect(img['bbox'])
            新 = fitz.Rect(原)
            for bb, size in 文字们:
                if size > 阈值:
                    continue                       # 正文字号 → 不是图里的字
                if 跳过bb and any(bb.intersects(s) for s in 跳过bb):
                    continue                       # 已摘走的边缘竖排,别再并进图
                dx = max(原.x0 - bb.x1, bb.x0 - 原.x1, 0)
                dy = max(原.y0 - bb.y1, bb.y0 - 原.y1, 0)
                if max(dx, dy) > 15:
                    continue                       # 离图太远
                新 |= bb
            if 新 == 原:
                结果.append(img)
                continue
            try:
                结果.append(ie.clip_page_to_dict(bbox=新, rm_image=True,
                                                 clip_image_res_ratio=ratio,
                                                 rm_text=False))
            except Exception:
                logging.warning('svg expand failed: %s', 新)
                结果.append(img)
        return 结果


    def _formula_image_blocks(self, 公式区, settings):
        '''把公式区域渲染成 PNG,包成 image block。'''
        dpi = settings.get('formula_image_dpi', 200)
        blocks = []
        for f in 公式区:
            try:
                clip = fitz.Rect(f['bbox'])
                pix = self.page_engine.get_pixmap(clip=clip, dpi=dpi)
                blocks.append({
                    'type': BlockType.IMAGE.value,
                    'bbox': tuple(clip),
                    'width': pix.width,
                    'height': pix.height,
                    'image': pix.tobytes('png'),
                })
            except Exception:
                logging.warning('formula block skipped: %s', f)
        return blocks


    def _preprocess_text(self, **settings):
        '''Extract page text and identify hidden text. 
        
        NOTE: All the coordinates are relative to un-rotated page.

            https://pymupdf.readthedocs.io/en/latest/page.html#modifying-pages
            https://pymupdf.readthedocs.io/en/latest/functions.html#Page.get_texttrace
            https://pymupdf.readthedocs.io/en/latest/textpage.html
        '''
        ocr = settings['ocr']
        if ocr==1: raise SystemExit("OCR feature is planned but not implemented yet.")

        # all text blocks no matter hidden or not
        sort = settings.get('sort')
        raw = self.page_engine.get_text(
                'rawdict',
                flags=0
                    | fitz.TEXT_MEDIABOX_CLIP
                    | fitz.TEXT_CID_FOR_UNKNOWN_UNICODE
                    ,
                sort=sort,
                )
        text_blocks = raw.get('blocks', [])

        # potential UnicodeDecodeError issue when trying to filter hidden text:
        # https://github.com/dothinking/pdf2docx/issues/144
        # https://github.com/dothinking/pdf2docx/issues/155
        try:
            spans = self.page_engine.get_texttrace()
        except SystemError:
            logging.warning('Ignore hidden text checking due to UnicodeDecodeError in upstream library.')
            spans = []
        
        if not spans: return text_blocks

        # ignore hidden text if ocr=0, while extract only hidden text if ocr=2
        if ocr==2:
            f = lambda span: span['type']!=3  # find displayed text and ignore it
        else:
            f = lambda span: span['type']==3  # find hidden text and ignore it
        filtered_spans = list(filter(f, spans))
        
        def span_area(bbox):
            x0, y0, x1, y1 = bbox
            return (x1-x0) * (y1-y0)

        # filter blocks by checking span intersection: mark the entire block if 
        # any span is matched
        blocks = []
        for block in text_blocks:
            intersected = False
            for line in block['lines']:
                for span in line['spans']:
                    for filter_span in filtered_spans:
                        intersected_area = get_area(span['bbox'], filter_span['bbox'])
                        if intersected_area / span_area(span['bbox']) >= FACTOR_A_HALF \
                            and span['font']==filter_span['font']:
                            intersected = True
                            break
                    if intersected: break # skip further span check if found
                if intersected: break     # skip further line check

            # keep block if no any intersection with filtered span
            if not intersected: blocks.append(block)

        return blocks


    def _preprocess_images(self, **settings):
        '''Extract image blocks. Image block extracted by ``page.get_text('rawdict')`` doesn't 
        contain alpha channel data, so it has to get page images by ``page.get_images()`` and 
        then recover them. Note that ``Page.get_images()`` contains each image only once, i.e., 
        ignore duplicated occurrences.
        '''
        # ignore image if ocr-ed pdf: get ocr-ed text only
        if settings['ocr']==2: return []
        
        return ImagesExtractor(self.page_engine).extract_images(settings['clip_image_res_ratio'])


    def _preprocess_shapes(self, **settings):
        '''Identify iso-oriented paths and convert vector graphic paths to pixmap.'''
        paths = self._init_paths(**settings)
        return paths.to_shapes_and_images(
            settings['min_svg_gap_dx'], 
            settings['min_svg_gap_dy'], 
            settings['min_svg_w'], 
            settings['min_svg_h'], 
            settings['clip_image_res_ratio'])
    

    @debug_plot('Source Paths')
    def _init_paths(self, **settings):
        '''Initialize Paths based on drawings extracted with PyMuPDF.'''
        raw_paths = self.page_engine.get_cdrawings()
        return Paths(parent=self).restore(raw_paths)
    

    def _preprocess_hyperlinks(self):
        """Get source hyperlink dicts.

        Returns:
            list: A list of source hyperlink dict.
        """
        hyperlinks = []
        for link in self.page_engine.get_links():
            if link['kind']!=2: continue # consider internet address only
            hyperlinks.append({
                'type': RectType.HYPERLINK.value,
                'bbox': tuple(link['from']),
                'uri' : link['uri']
            })

        return hyperlinks
